  `tolerance_minus_cm` decimal(6,2) NOT NULL DEFAULT '0.00',
  `source` varchar(32) COLLATE utf8mb4_general_ci NOT NULL DEFAULT 'vendor',
  `is_estimated` tinyint(1) NOT NULL DEFAULT '0',
  `notes` varchar(500) COLLATE utf8mb4_general_ci DEFAULT NULL,
  `created_at` datetime NOT NULL,
  `updated_at` datetime NOT NULL,
  PRIMARY KEY (`id`),
  UNIQUE KEY `uq_garment_measurements_variant_type` (`variant_id`,`measurement_type_id`),
  KEY `idx_garment_measurements_type` (`measurement_type_id`),
  CONSTRAINT `garment_measurements_ibfk_1` FOREIGN KEY (`variant_id`) REFERENCES `product_variants` (`id`) ON DELETE CASCADE ON UPDATE CASCADE,
  CONSTRAINT `garment_measurements_ibfk_2` FOREIGN KEY (`measurement_type_id`) REFERENCES `garment_measurement_types` (`id`) ON DELETE RESTRICT ON UPDATE CASCADE
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_general_ci;

CREATE TABLE `guest_sessions` (
  `id` bigint unsigned NOT NULL AUTO_INCREMENT,
  `session_uuid` char(36) COLLATE utf8mb4_general_ci NOT NULL,
  `installation_id_hash` char(64) COLLATE utf8mb4_general_ci NOT NULL,
  `token_version` int unsigned NOT NULL DEFAULT '1',
  `platform` varchar(20) COLLATE utf8mb4_general_ci NOT NULL,
  `app_version` varchar(50) COLLATE utf8mb4_general_ci DEFAULT NULL,
  `locale` varchar(5) COLLATE utf8mb4_general_ci NOT NULL DEFAULT 'it',
  `status` varchar(20) COLLATE utf8mb4_general_ci NOT NULL DEFAULT 'active',
  `converted_account_id` bigint unsigned DEFAULT NULL,
  `last_seen_at` datetime NOT NULL,
  `expires_at` datetime NOT NULL,
  `created_at` datetime NOT NULL,
  `updated_at` datetime NOT NULL,
  PRIMARY KEY (`id`),
  UNIQUE KEY `uq_guest_sessions_session_uuid` (`session_uuid`),
  KEY `idx_guest_sessions_installation` (`installation_id_hash`,`platform`,`status`),
  KEY `idx_guest_sessions_converted_account` (`converted_account_id`),
  KEY `idx_guest_sessions_expires_at` (`expires_at`),
  CONSTRAINT `guest_sessions_ibfk_1` FOREIGN KEY (`converted_account_id`) REFERENCES `accounts` (`id`) ON DELETE SET NULL ON UPDATE CASCADE
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_general_ci;

CREATE TABLE `home_placements` (
  `id` bigint unsigned NOT NULL AUTO_INCREMENT,
  `section_key` varchar(40) COLLATE utf8mb4_general_ci NOT NULL,
  `target_type` varchar(32) COLLATE utf8mb4_general_ci NOT NULL,
  `target_product_id` bigint unsigned DEFAULT NULL,
  `target_brand_id` bigint unsigned DEFAULT NULL,
  `target_category_id` bigint unsigned DEFAULT NULL,
  `target_filters` json DEFAULT NULL,
  `image_storage_key` varchar(500) COLLATE utf8mb4_general_ci DEFAULT NULL,
  `image_width` int unsigned DEFAULT NULL,
  `image_height` int unsigned DEFAULT NULL,
  `title_en` varchar(200) COLLATE utf8mb4_general_ci DEFAULT NULL,
  `title_it` varchar(200) COLLATE utf8mb4_general_ci DEFAULT NULL,
  `subtitle_en` varchar(500) COLLATE utf8mb4_general_ci DEFAULT NULL,
  `subtitle_it` varchar(500) COLLATE utf8mb4_general_ci DEFAULT NULL,
  `cta_label_en` varchar(100) COLLATE utf8mb4_general_ci DEFAULT NULL,
  `cta_label_it` varchar(100) COLLATE utf8mb4_general_ci DEFAULT NULL,
  `alt_text_en` varchar(255) COLLATE utf8mb4_general_ci DEFAULT NULL,
  `alt_text_it` varchar(255) COLLATE utf8mb4_general_ci DEFAULT NULL,
  `status` varchar(20) COLLATE utf8mb4_general_ci NOT NULL DEFAULT 'draft',
  `starts_at` datetime DEFAULT NULL,
  `ends_at` datetime DEFAULT NULL,
  `sort_order` int unsigned NOT NULL DEFAULT '0',
  `created_at` datetime NOT NULL,
  `updated_at` datetime NOT NULL,
  `deleted_at` datetime DEFAULT NULL,
  `link_path` varchar(500) COLLATE utf8mb4_general_ci DEFAULT NULL,
  `link_query` json DEFAULT NULL,
  `external_url` varchar(2048) COLLATE utf8mb4_general_ci DEFAULT NULL,
  `offer_payload` json DEFAULT NULL,
  `badge_en` varchar(100) COLLATE utf8mb4_general_ci DEFAULT NULL,
  `badge_it` varchar(100) COLLATE utf8mb4_general_ci DEFAULT NULL,
  `discount_label_en` varchar(100) COLLATE utf8mb4_general_ci DEFAULT NULL,
  `discount_label_it` varchar(100) COLLATE utf8mb4_general_ci DEFAULT NULL,
  `image_content_type` varchar(100) COLLATE utf8mb4_general_ci DEFAULT NULL,
  `image_size_bytes` int unsigned DEFAULT NULL,
  `source` varchar(20) COLLATE utf8mb4_general_ci NOT NULL DEFAULT 'admin',
  `created_by_account_id` bigint unsigned DEFAULT NULL,
  `updated_by_account_id` bigint unsigned DEFAULT NULL,
  `published_by_account_id` bigint unsigned DEFAULT NULL,
  `published_at` datetime DEFAULT NULL,
  PRIMARY KEY (`id`),
  KEY `idx_home_placements_feed` (`section_key`,`status`,`starts_at`,`ends_at`,`sort_order`),
  KEY `idx_home_placements_product` (`target_product_id`),
  KEY `idx_home_placements_brand` (`target_brand_id`),
  KEY `idx_home_placements_category` (`target_category_id`),
  KEY `idx_home_placements_source_status` (`source`,`status`),
  KEY `idx_home_placements_created_by` (`created_by_account_id`),
  KEY `idx_home_placements_updated_by` (`updated_by_account_id`),
  KEY `idx_home_placements_published_by` (`published_by_account_id`),
  CONSTRAINT `home_placements_created_by_account_id_foreign_idx` FOREIGN KEY (`created_by_account_id`) REFERENCES `accounts` (`id`) ON DELETE SET NULL ON UPDATE CASCADE,
  CONSTRAINT `home_placements_ibfk_1` FOREIGN KEY (`target_product_id`) REFERENCES `products` (`id`) ON DELETE SET NULL ON UPDATE CASCADE,
  CONSTRAINT `home_placements_ibfk_2` FOREIGN KEY (`target_brand_id`) REFERENCES `brands` (`id`) ON DELETE SET NULL ON UPDATE CASCADE,
  CONSTRAINT `home_placements_ibfk_3` FOREIGN KEY (`target_category_id`) REFERENCES `categories` (`id`) ON DELETE SET NULL ON UPDATE CASCADE,
  CONSTRAINT `home_placements_published_by_account_id_foreign_idx` FOREIGN KEY (`published_by_account_id`) REFERENCES `accounts` (`id`) ON DELETE SET NULL ON UPDATE CASCADE,
  CONSTRAINT `home_placements_updated_by_account_id_foreign_idx` FOREIGN KEY (`updated_by_account_id`) REFERENCES `accounts` (`id`) ON DELETE SET NULL ON UPDATE CASCADE
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_general_ci;

CREATE TABLE `inventory` (
  `id` bigint unsigned NOT NULL AUTO_INCREMENT,
  `variant_id` bigint unsigned NOT NULL,
  `quantity_on_hand` int unsigned NOT NULL DEFAULT '0',
  `quantity_reserved` int unsigned NOT NULL DEFAULT '0',
  `reorder_point` int unsigned NOT NULL DEFAULT '0',
  `safety_stock` int unsigned NOT NULL DEFAULT '0',
  `allow_backorder` tinyint(1) NOT NULL DEFAULT '0',
  `stock_version` int unsigned NOT NULL DEFAULT '0',
  `created_at` datetime NOT NULL,
  `updated_at` datetime NOT NULL,
  PRIMARY KEY (`id`),
  UNIQUE KEY `uq_inventory_variant` (`variant_id`),
  CONSTRAINT `inventory_ibfk_1` FOREIGN KEY (`variant_id`) REFERENCES `product_variants` (`id`) ON DELETE CASCADE ON UPDATE CASCADE
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_general_ci;

CREATE TABLE `languages` (
  `id` bigint unsigned NOT NULL AUTO_INCREMENT,
  `code` varchar(10) COLLATE utf8mb4_general_ci NOT NULL,
  `name` varchar(100) COLLATE utf8mb4_general_ci NOT NULL,
  `is_default` tinyint(1) NOT NULL DEFAULT '0',
  `is_active` tinyint(1) NOT NULL DEFAULT '1',
  `created_at` datetime NOT NULL,
  `updated_at` datetime NOT NULL,
  PRIMARY KEY (`id`),
  UNIQUE KEY `uq_languages_code` (`code`)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_general_ci;

CREATE TABLE `order_fulfillments` (
  `id` bigint unsigned NOT NULL AUTO_INCREMENT,
  `order_id` bigint unsigned NOT NULL,
  `carrier` varchar(120) COLLATE utf8mb4_general_ci NOT NULL,
  `tracking_number` varchar(191) COLLATE utf8mb4_general_ci NOT NULL,
  `tracking_url` varchar(2048) COLLATE utf8mb4_general_ci DEFAULT NULL,
  `shipped_at` datetime DEFAULT NULL,
  `created_at` datetime NOT NULL,
  `updated_at` datetime NOT NULL,
  PRIMARY KEY (`id`),
  UNIQUE KEY `order_id` (`order_id`),
  CONSTRAINT `order_fulfillments_ibfk_1` FOREIGN KEY (`order_id`) REFERENCES `orders` (`id`) ON DELETE CASCADE ON UPDATE CASCADE
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_general_ci;

CREATE TABLE `order_items` (
  `id` bigint unsigned NOT NULL AUTO_INCREMENT,
  `order_id` bigint unsigned NOT NULL,
  `product_id` bigint unsigned DEFAULT NULL,
  `product_variant_id` bigint unsigned DEFAULT NULL,
  `product_snapshot` json NOT NULL,
  `quantity` smallint unsigned NOT NULL,
  `unit_price` decimal(12,2) NOT NULL,
  `regular_price` decimal(12,2) NOT NULL,
  `line_total` decimal(12,2) NOT NULL,
  `created_at` datetime NOT NULL,
  `updated_at` datetime NOT NULL,
  PRIMARY KEY (`id`),
  KEY `idx_order_items_order` (`order_id`),
  CONSTRAINT `order_items_ibfk_1` FOREIGN KEY (`order_id`) REFERENCES `orders` (`id`) ON DELETE CASCADE ON UPDATE CASCADE
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_general_ci;

CREATE TABLE `order_return_items` (
  `id` bigint unsigned NOT NULL AUTO_INCREMENT,
  `order_return_id` bigint unsigned NOT NULL,
  `order_item_id` bigint unsigned NOT NULL,
  `product_snapshot` json NOT NULL,
  `quantity` smallint unsigned NOT NULL,
  `reason` varchar(24) COLLATE utf8mb4_general_ci NOT NULL,
  `note` varchar(1000) COLLATE utf8mb4_general_ci DEFAULT NULL,
  `unit_price` decimal(12,2) NOT NULL,
  `line_total` decimal(12,2) NOT NULL,
  `created_at` datetime NOT NULL,
  `updated_at` datetime NOT NULL,
  PRIMARY KEY (`id`),
  KEY `idx_order_return_items_return` (`order_return_id`),
  KEY `idx_order_return_items_order_item` (`order_item_id`),
  CONSTRAINT `order_return_items_ibfk_1` FOREIGN KEY (`order_return_id`) REFERENCES `order_returns` (`id`) ON DELETE CASCADE ON UPDATE CASCADE,
  CONSTRAINT `order_return_items_ibfk_2` FOREIGN KEY (`order_item_id`) REFERENCES `order_items` (`id`) ON DELETE RESTRICT ON UPDATE CASCADE
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_general_ci;

CREATE TABLE `order_returns` (
  `id` bigint unsigned NOT NULL AUTO_INCREMENT,
  `order_id` bigint unsigned NOT NULL,
  `account_id` bigint unsigned NOT NULL,
  `status` varchar(24) COLLATE utf8mb4_general_ci NOT NULL DEFAULT 'requested',
  `refund_status` varchar(32) COLLATE utf8mb4_general_ci NOT NULL DEFAULT 'not_started',
  `refund_method` varchar(32) COLLATE utf8mb4_general_ci DEFAULT NULL,
  `refund_provider` varchar(40) COLLATE utf8mb4_general_ci DEFAULT NULL,
  `provider_refund_id` varchar(191) COLLATE utf8mb4_general_ci DEFAULT NULL,
  `created_at` datetime NOT NULL,
  `updated_at` datetime NOT NULL,
  PRIMARY KEY (`id`),
  KEY `idx_order_returns_order` (`order_id`),
  KEY `idx_order_returns_account_created` (`account_id`,`created_at`),
  CONSTRAINT `order_returns_ibfk_1` FOREIGN KEY (`order_id`) REFERENCES `orders` (`id`) ON DELETE CASCADE ON UPDATE CASCADE,
  CONSTRAINT `order_returns_ibfk_2` FOREIGN KEY (`account_id`) REFERENCES `accounts` (`id`) ON DELETE CASCADE ON UPDATE CASCADE
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_general_ci;

CREATE TABLE `orders` (
  `id` bigint unsigned NOT NULL AUTO_INCREMENT,
  `account_id` bigint unsigned NOT NULL,
  `order_number` varchar(32) COLLATE utf8mb4_general_ci NOT NULL,
  `status` varchar(32) COLLATE utf8mb4_general_ci NOT NULL DEFAULT 'placed',
  `payment_mode` varchar(20) COLLATE utf8mb4_general_ci NOT NULL,
  `currency_code` char(3) COLLATE utf8mb4_general_ci NOT NULL DEFAULT 'EUR',
  `subtotal` decimal(12,2) NOT NULL,
  `discount` decimal(12,2) NOT NULL DEFAULT '0.00',
  `shipping_fee` decimal(12,2) NOT NULL,
  `cod_fee` decimal(12,2) NOT NULL DEFAULT '0.00',
  `total` decimal(12,2) NOT NULL,
  `vat_included` decimal(12,2) NOT NULL,
  `shipping_method` varchar(20) COLLATE utf8mb4_general_ci NOT NULL,
  `address_snapshot` json NOT NULL,
  `created_at` datetime NOT NULL,
  `updated_at` datetime NOT NULL,
  `delivered_at` datetime DEFAULT NULL,
  `cancelled_at` datetime DEFAULT NULL,
  `cancel_reason` varchar(24) COLLATE utf8mb4_general_ci DEFAULT NULL,
  `cancel_note` varchar(1000) COLLATE utf8mb4_general_ci DEFAULT NULL,
  PRIMARY KEY (`id`),
  UNIQUE KEY `order_number` (`order_number`),
  KEY `idx_orders_account_created` (`account_id`,`created_at`),
  CONSTRAINT `orders_ibfk_1` FOREIGN KEY (`account_id`) REFERENCES `accounts` (`id`) ON DELETE CASCADE ON UPDATE CASCADE
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_general_ci;

CREATE TABLE `payments` (
  `id` bigint unsigned NOT NULL AUTO_INCREMENT,
