  `account_id` bigint unsigned NOT NULL,
  `order_item_id` bigint unsigned DEFAULT NULL,
  `rating` tinyint unsigned NOT NULL,
  `title` varchar(180) COLLATE utf8mb4_general_ci DEFAULT NULL,
  `body` text COLLATE utf8mb4_general_ci,
  `recommends` tinyint(1) DEFAULT NULL,
  `fit_feedback` varchar(10) COLLATE utf8mb4_general_ci DEFAULT NULL,
  `reviewer_height_cm` smallint unsigned DEFAULT NULL,
  `purchased_size_label` varchar(64) COLLATE utf8mb4_general_ci DEFAULT NULL,
  `purchased_color_name` varchar(100) COLLATE utf8mb4_general_ci DEFAULT NULL,
